-- Forward-only Skill/version scope; immutable historical OC columns remain readable.
ALTER TABLE platform.assessment_item_knowledge_mapping ALTER COLUMN outcome_code DROP NOT NULL;
ALTER TABLE platform.rule_assessment_group DROP CONSTRAINT rule_assessment_group_outcome_codes_check;
ALTER TABLE platform.rule_assessment_group ADD CONSTRAINT rule_assessment_group_outcome_codes_check CHECK (jsonb_typeof(outcome_codes)='array');
CREATE TABLE platform.assessment_item_skill_scope (
    item_version_id uuid PRIMARY KEY REFERENCES platform.assessment_item_knowledge_mapping,
    skill_version text NOT NULL CHECK (btrim(skill_version)<>''),
    source text NOT NULL CHECK (source IN ('PUBLICATION','FROZEN_CONTEXT','PINNED_DEVELOPMENT_RELEASE'))
);
-- Existing frozen contexts are authoritative only when every observation agrees on a version.
INSERT INTO platform.assessment_item_skill_scope(item_version_id,skill_version,source)
SELECT i.item_version_id,min(d->>'skillVersion'),'FROZEN_CONTEXT'
FROM platform.rule_assessment_item i
JOIN platform.rule_assessment_group g ON g.attempt_id=i.attempt_id AND g.group_id=i.group_id
JOIN platform.rule_assessment_attempt a ON a.id=i.attempt_id
CROSS JOIN LATERAL jsonb_array_elements(a.context_snapshot->'context'->'requirements') d
WHERE d->'requirement'->>'skillId'=g.skill_id AND d->'requirement'->>'knowledgeLevel'=g.knowledge_level
    AND nullif(d->>'skillVersion','') IS NOT NULL
GROUP BY i.item_version_id HAVING count(DISTINCT d->>'skillVersion')=1;
-- Exact original manifest identities and mapping hashes; never infer another publisher's Skill version.
