CREATE INDEX rule_item_skill_version ON platform.assessment_item_skill_scope(skill_version,item_version_id);
-- Sidecars follow the same append-only rule as published mappings.
CREATE FUNCTION platform.reject_item_skill_scope_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Published Skill scope is immutable' USING ERRCODE='23514'; END; $$;
CREATE TRIGGER immutable_item_skill_scope BEFORE UPDATE OR DELETE ON platform.assessment_item_skill_scope
    FOR EACH ROW EXECUTE FUNCTION platform.reject_item_skill_scope_update();
